CREATE OR REPLACE FUNCTION public.estrategia_fonte_visivel(_tipo text, _id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN _tipo='acao' THEN EXISTS(SELECT 1 FROM public.gov_acoes a WHERE a.id=_id AND (public.gov_is_admin(auth.uid()) OR public.gov_diretor_da_acao(auth.uid(),a.responsavel_normalizado))) WHEN _tipo='decisao' THEN EXISTS(SELECT 1 FROM public.decisoes_estrategicas d WHERE d.id=_id AND public.fase1_acesso('decisoes') AND (d.acesso_reservado IS NOT TRUE OR public.is_super_admin(auth.uid()) OR public.has_role(auth.uid(),'admin'))) ELSE false END $$;
REVOKE ALL ON FUNCTION public.estrategia_fonte_visivel(text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.estrategia_fonte_visivel(text,uuid) TO authenticated,service_role;
CREATE TABLE public.estrategia_ia_execucoes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), criado_por uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'gerando' CHECK(status IN('gerando','concluido','erro','pausado')), fontes text[] NOT NULL DEFAULT '{}', analisados integer NOT NULL DEFAULT 0, sugestoes integer NOT NULL DEFAULT 0, erro text, bloqueio text, run_id text);
GRANT SELECT ON public.estrategia_ia_execucoes TO authenticated; GRANT ALL ON public.estrategia_ia_execucoes TO service_role;
ALTER TABLE public.estrategia_ia_execucoes ENABLE ROW LEVEL SECURITY;
CREATE POLICY estrategia_exec_ler ON public.estrategia_ia_execucoes FOR SELECT TO authenticated USING(public.proj_gov_ou_ceo(auth.uid()) AND criado_por=auth.uid());
CREATE UNIQUE INDEX estrategia_ia_uma_execucao ON public.estrategia_ia_execucoes((status)) WHERE status='gerando';
CREATE TABLE public.estrategia_sugestoes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), origem_tipo text NOT NULL CHECK(origem_tipo IN('acao','decisao')), origem_id uuid NOT NULL, tipo text NOT NULL CHECK(tipo IN('objetivo','indicador')), ref_id uuid NOT NULL, justificativa text NOT NULL, trecho text NOT NULL, confianca text NOT NULL CHECK(confianca IN('alta','media','baixa')), status text NOT NULL DEFAULT 'pendente' CHECK(status IN('pendente','aprovada','rejeitada')), execucao_id uuid REFERENCES public.estrategia_ia_execucoes(id), created_at timestamptz NOT NULL DEFAULT now(), revisado_por uuid, revisado_em timestamptz, aprovado_tipo text, aprovado_ref_id uuid, UNIQUE(origem_tipo,origem_id,tipo,ref_id));
GRANT SELECT ON public.estrategia_sugestoes TO authenticated; GRANT ALL ON public.estrategia_sugestoes TO service_role;
ALTER TABLE public.estrategia_sugestoes ENABLE ROW LEVEL SECURITY;
CREATE POLICY estrategia_sug_ler ON public.estrategia_sugestoes FOR SELECT TO authenticated USING(public.proj_gov_ou_ceo(auth.uid()) AND public.estrategia_fonte_visivel(origem_tipo,origem_id));
CREATE TABLE public.estrategia_sugestoes_auditoria(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sugestao_id uuid NOT NULL REFERENCES public.estrategia_sugestoes(id), acao text NOT NULL CHECK(acao IN('aprovar','rejeitar','gerar_novamente')), usuario_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), tipo text, ref_id uuid);
GRANT SELECT ON public.estrategia_sugestoes_auditoria TO authenticated; GRANT ALL ON public.estrategia_sugestoes_auditoria TO service_role;
ALTER TABLE public.estrategia_sugestoes_auditoria ENABLE ROW LEVEL SECURITY;
CREATE POLICY estrategia_audit_ler ON public.estrategia_sugestoes_auditoria FOR SELECT TO authenticated USING(public.proj_gov_ou_ceo(auth.uid()) AND EXISTS(SELECT 1 FROM public.estrategia_sugestoes s WHERE s.id=sugestao_id));
CREATE OR REPLACE FUNCTION public.estrategia_alvo_ativo(_tipo text,_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN _tipo='objetivo' THEN EXISTS(SELECT 1 FROM public.mt_objetivos WHERE id=_id) WHEN _tipo='indicador' THEN EXISTS(SELECT 1 FROM public.mt_indicadores i LEFT JOIN public.mt_okrs o ON o.id=i.okr_id WHERE i.id=_id AND i.status='ativo' AND (i.origem<>'okr' OR o.semestre=to_char(now() AT TIME ZONE 'America/Sao_Paulo','YYYY')||'/'||CASE WHEN extract(month FROM now() AT TIME ZONE 'America/Sao_Paulo')<=6 THEN '1' ELSE '2' END)) ELSE false END $$;
REVOKE ALL ON FUNCTION public.estrategia_alvo_ativo(text,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.estrategia_alvo_ativo(text,uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.estrategia_revisar_sugestoes(_itens jsonb,_acao text) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE item jsonb; s public.estrategia_sugestoes%ROWTYPE; t text; r uuid; n integer:=0; BEGIN IF NOT public.proj_gov_ou_ceo(auth.uid()) THEN RAISE EXCEPTION 'Apenas Governança e CEO.'; END IF; IF _acao NOT IN('aprovar','rejeitar') OR jsonb_typeof(_itens)<>'array' OR jsonb_array_length(_itens) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Seleção inválida (1–100).'; END IF; FOR item IN SELECT value FROM jsonb_array_elements(_itens) ORDER BY value->>'id' LOOP SELECT * INTO s FROM public.estrategia_sugestoes WHERE id=(item->>'id')::uuid FOR UPDATE; IF NOT FOUND OR s.status<>'pendente' OR NOT public.estrategia_fonte_visivel(s.origem_tipo,s.origem_id) THEN RAISE EXCEPTION 'Sugestão indisponível ou já revisada.'; END IF; t:=coalesce(item->>'tipo',s.tipo); r:=coalesce((item->>'ref_id')::uuid,s.ref_id); IF _acao='aprovar' THEN IF NOT public.estrategia_alvo_ativo(t,r) THEN RAISE EXCEPTION 'O item selecionado não está vigente.'; END IF; INSERT INTO public.estrategia_vinculos_gov(origem_tipo,origem_id,tipo,ref_id,criado_por) VALUES(s.origem_tipo,s.origem_id,t,r,auth.uid()) ON CONFLICT(origem_tipo,origem_id,tipo,ref_id) DO NOTHING; END IF; UPDATE public.estrategia_sugestoes SET status=CASE WHEN _acao='aprovar' THEN 'aprovada' ELSE 'rejeitada' END,revisado_por=auth.uid(),revisado_em=now(),aprovado_tipo=CASE WHEN _acao='aprovar' THEN t END,aprovado_ref_id=CASE WHEN _acao='aprovar' THEN r END WHERE id=s.id; INSERT INTO public.estrategia_sugestoes_auditoria(sugestao_id,acao,usuario_id,tipo,ref_id) VALUES(s.id,_acao,auth.uid(),t,r); n:=n+1; END LOOP; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.estrategia_revisar_sugestoes(jsonb,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.estrategia_revisar_sugestoes(jsonb,text) TO authenticated;